<section class="panel"><h2>Item categories</h2><table><tr><th>Name</th><?php if(manager()): ?><th>Actions</th><?php endif ?></tr><?php $rows=query('SELECT * FROM categories ORDER BY name')->fetchAll(); foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><?php if(manager()): ?><td class="actions"><a href="?page=categories&edit=<?= $r['id'] ?>">Edit</a><?php deleteForm('delete_category',$r['id']); ?></td><?php endif ?></tr><?php endforeach ?></table><?php if(!$rows) echo '<p class="empty">No categories yet.</p>'; ?></section>
<?php if(manager()): $r=query('SELECT * FROM categories WHERE id=?',[(int)($_GET['edit']??0)])->fetch()?:[]; ?><section class="panel"><h2><?= $r?'Edit category':'Add category' ?></h2><?php startForm('save_category',$r['id']??0); field('name','Category name',$r['name']??''); endForm(); ?></section><?php endif ?>
